alter table public.users_profile enable row level security; alter table public.program_profiles enable row level security; alter table public.document_reviews enable row level security; alter table public.financial_reviews enable row level security; alter table public.interview_sessions enable row level security; alter table public.final_reports enable row level security; alter table public.uploads enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer as $$ select exists (select 1 from public.users_profile where user_id = auth.uid() and role = 'admin') $$;
do $$ declare t text; begin foreach t in array array['users_profile','program_profiles','document_reviews','financial_reviews','interview_sessions','final_reports','uploads'] loop execute format('drop policy if exists "Users manage own %1$s" on public.%1$I', t); execute format('create policy "Users manage own %1$s" on public.%1$I for all using (auth.uid() = user_id or public.is_admin()) with check (auth.uid() = user_id or public.is_admin())', t); end loop; end $$;
create policy "Users upload own private files" on storage.objects for insert with check (bucket_id = 'brovi-private-uploads' and auth.uid()::text = (storage.foldername(name))[1]);
create policy "Users read own private files" on storage.objects for select using (bucket_id = 'brovi-private-uploads' and (auth.uid()::text = (storage.foldername(name))[1] or public.is_admin()));
create policy "Users update own private files" on storage.objects for update using (bucket_id = 'brovi-private-uploads' and auth.uid()::text = (storage.foldername(name))[1]);
create policy "Users delete own private files" on storage.objects for delete using (bucket_id = 'brovi-private-uploads' and auth.uid()::text = (storage.foldername(name))[1]);
